import type { KnowledgeHit } from '../../integrations/ragflow/ragflow.normalize.js';

// Extractive answers deliberately bypass the small generative model. Identifiers,
// amounts and dates remain source text, not tokens regenerated by an LLM.
export function groundedAnswer(hits: readonly KnowledgeHit[]) {
  const selected = hits.filter(x => typeof x.similarity === 'number' && x.similarity >= 0.35 && x.content.trim()).slice(0, 3);
  return { mode: 'extractive' as const, answered: selected.length > 0,
    answer: selected.length ? selected.map((x, i) => `[${i + 1}] ${x.content}`).join('\n\n') : '未找到足够可靠且已获授权的资料。',
    sources: selected.map((x, i) => ({ number: i + 1, documentId: x.documentId, versionId: x.versionId, chunkId: x.chunkId, content: x.content })) };
}
